//! DML generated by the data editor (grid edits → INSERT / UPDATE / DELETE), with literal values
//! like SQL Developer's generated statements.

use crate::dialect::{placeholder, quote};
use crate::registry::Kind as Db;
use crate::{Cell, Column};

/// Oracle DATE/TIMESTAMP cells are rendered with the session NLS formats, so a plain string
/// literal converts back implicitly.
pub fn literal(db: Db, col: &Column, v: &Cell) -> String {
    let Some(s) = v else { return "NULL".into() };
    // Spilled LOB cells: the literal needs the whole value.
    let full = crate::lob::expand(s);
    let s = &full.into_owned();
    if col.numeric && !s.is_empty() && s.parse::<f64>().is_ok() {
        return s.clone();
    }
    // Binary cells hold hex text: write it back as that engine's hex literal.
    if crate::is_binary(&col.type_name) {
        let b = crate::cell_bytes(col, s);
        let h: String = b.iter().map(|x| format!("{x:02X}")).collect();
        return match db {
            Db::Oracle => format!("HEXTORAW('{h}')"),
            Db::Postgres => format!("'\\x{h}'::bytea"),
            Db::Mssql => format!("0x{h}"),
            Db::Duckdb | Db::Clickhouse => format!("unhex('{h}')"),
            Db::Mysql | Db::Sqlite => format!("X'{h}'"),
        };
    }
    let t = col.type_name.to_uppercase();
    // ISO dates (imports, typed values) convert explicitly: they rarely match NLS_DATE_FORMAT.
    if db == Db::Oracle && (t == "DATE" || t.starts_with("TIMESTAMP")) && !t.contains("TIME ZONE") {
        if let Some((v, fmt)) = iso_datetime(s) {
            return format!("TO_TIMESTAMP('{v}', '{fmt}')");
        }
    }
    let q = format!("'{}'", s.replace('\'', "''"));
    match db {
        Db::Mssql if t.contains("NVARCHAR") || t.contains("NCHAR") || t.contains("NTEXT") => format!("N{q}"),
        _ => q,
    }
}

/// Oracle rejects string literals over 4000 bytes (ORA-01704): longer text (CLOB edits) must be
/// bound. Other engines take long literals fine.
pub fn text_needs_bind(db: Db, col: &Column, v: &Cell) -> bool {
    db == Db::Oracle && !crate::is_binary(&col.type_name) && v.as_ref().is_some_and(|s| s.len() > 4000)
}

/// `YYYY-MM-DD[( |T)HH:MM[:SS[.fff]]]` → normalized value and its Oracle format model.
fn iso_datetime(s: &str) -> Option<(String, &'static str)> {
    let digits = |p: &str, n: usize| p.len() == n && p.bytes().all(|b| b.is_ascii_digit());
    let (date, time) = match s.split_once([' ', 'T']) {
        Some((d, t)) => (d, Some(t)),
        None => (s, None),
    };
    let d: Vec<&str> = date.split('-').collect();
    if !(d.len() == 3 && digits(d[0], 4) && digits(d[1], 2) && digits(d[2], 2)) {
        return None;
    }
    let Some(time) = time else { return Some((date.to_string(), "YYYY-MM-DD")) };
    let (hms, frac) = match time.split_once('.') {
        Some((a, f)) if (1..=9).contains(&f.len()) && f.bytes().all(|b| b.is_ascii_digit()) => (a, Some(f)),
        Some(_) => return None,
        None => (time, None),
    };
    let t: Vec<&str> = hms.split(':').collect();
    if !((t.len() == 2 || t.len() == 3) && t.iter().all(|p| digits(p, 2))) {
        return None;
    }
    let sec = t.get(2).copied().unwrap_or("00");
    Some(match frac {
        Some(f) => (format!("{date} {}:{}:{sec}.{f}", t[0], t[1]), "YYYY-MM-DD HH24:MI:SS.FF"),
        None => (format!("{date} {}:{}:{sec}", t[0], t[1]), "YYYY-MM-DD HH24:MI:SS"),
    })
}

/// How rows are identified for UPDATE/DELETE.
pub struct Key {
    /// Column indexes forming the key (row locator, PK, or every column as a last resort).
    pub cols: Vec<usize>,
    /// True when falling back to all columns: limit to one row.
    pub all_columns: bool,
}

impl Key {
    /// Primary key first (stable across updates; PostgreSQL ctid is not), then the row locator.
    pub fn new(cols: &[Column], hidden: Option<&str>, pk: &[String]) -> Key {
        let pk_idx: Vec<usize> = pk.iter().filter_map(|p| cols.iter().position(|c| c.name.eq_ignore_ascii_case(p))).collect();
        if !pk_idx.is_empty() && pk_idx.len() == pk.len() {
            return Key { cols: pk_idx, all_columns: false };
        }
        if let Some(h) = hidden {
            if let Some(i) = cols.iter().position(|c| c.name.eq_ignore_ascii_case(h)) {
                return Key { cols: vec![i], all_columns: false };
            }
        }
        Key { cols: (0..cols.len()).collect(), all_columns: true }
    }
}

fn cond(db: Db, cols: &[Column], key: &Key, row: &[Cell]) -> String {
    key.cols
        .iter()
        .map(|&i| {
            let c = &cols[i];
            let name = if c.name.eq_ignore_ascii_case("ROWID") || c.name == "ctid" || c.name == "rowid" { c.name.clone() } else { quote(db, &c.name) };
            match &row[i] {
                None => format!("{name} IS NULL"),
                v if db == Db::Postgres && c.name == "ctid" => format!("{name} = {}::tid", literal(db, c, v)),
                v if db == Db::Oracle && c.name.eq_ignore_ascii_case("ROWID") => format!("{name} = CHARTOROWID({})", literal(db, c, v)),
                v => format!("{name} = {}", literal(db, c, v)),
            }
        })
        .collect::<Vec<_>>()
        .join(" AND ")
}

fn one_row(db: Db, key: &Key) -> (&'static str, &'static str) {
    match (db, key.all_columns) {
        (Db::Mssql, true) => (" TOP (1)", ""),
        (Db::Mysql, true) => ("", " LIMIT 1"),
        (Db::Oracle, true) => ("", " AND ROWNUM = 1"),
        _ => ("", ""),
    }
}

/// Value for column `i`: a bind placeholder when it is in `binds` (staged BLOB bytes, bound in
/// `binds` order), otherwise a literal.
fn value(db: Db, binds: &[usize], i: usize, col: &Column, v: &Cell) -> String {
    match binds.iter().position(|&b| b == i) {
        Some(k) => placeholder(db, k + 1),
        None => literal(db, col, v),
    }
}

/// `skip` = hidden locator column, never written. `binds` = columns written from bind values.
pub fn update(db: Db, table: &str, cols: &[Column], key: &Key, skip: Option<usize>, old: &[Cell], new: &[Cell], binds: &[usize]) -> Option<String> {
    let sets: Vec<String> = (0..cols.len())
        .filter(|&i| Some(i) != skip && (old[i] != new[i] || binds.contains(&i)))
        .map(|i| format!("{} = {}", quote(db, &cols[i].name), value(db, binds, i, &cols[i], &new[i])))
        .collect();
    if sets.is_empty() {
        return None;
    }
    let (top, tail) = one_row(db, key);
    Some(format!("UPDATE{top} {table} SET {} WHERE {}{tail}", sets.join(", "), cond(db, cols, key, old)))
}

pub fn insert(db: Db, table: &str, cols: &[Column], skip: Option<usize>, row: &[Cell], binds: &[usize]) -> String {
    let idx: Vec<usize> = (0..cols.len()).filter(|&i| Some(i) != skip && (row[i].is_some() || binds.contains(&i))).collect();
    if idx.is_empty() {
        return match db {
            Db::Oracle | Db::Mysql => format!("INSERT INTO {table} VALUES (DEFAULT)"),
            _ => format!("INSERT INTO {table} DEFAULT VALUES"),
        };
    }
    format!(
        "INSERT INTO {table} ({}) VALUES ({})",
        idx.iter().map(|&i| quote(db, &cols[i].name)).collect::<Vec<_>>().join(", "),
        idx.iter().map(|&i| value(db, binds, i, &cols[i], &row[i])).collect::<Vec<_>>().join(", ")
    )
}

pub fn delete(db: Db, table: &str, cols: &[Column], key: &Key, row: &[Cell]) -> String {
    let (top, tail) = one_row(db, key);
    format!("DELETE{top} FROM {table} WHERE {}{tail}", cond(db, cols, key, row))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn col(n: &str, t: &str, numeric: bool) -> Column {
        Column { name: n.into(), type_name: t.into(), numeric }
    }

    #[test]
    fn generate() {
        let cols = vec![col("ROWID", "ROWID", false), col("ID", "NUMBER", true), col("NAME", "VARCHAR2", false), col("HIRED", "DATE", false)];
        let key = Key::new(&cols, Some("ROWID"), &[]);
        let old = vec![Some("AAA".into()), Some("1".into()), Some("O'Neil".into()), None];
        let mut new = old.clone();
        new[2] = Some("Bob".into());
        new[3] = Some("02-JAN-26".into());
        assert_eq!(
            update(Db::Oracle, "\"HR\".\"EMP\"", &cols, &key, Some(0), &old, &new, &[]).unwrap(),
            "UPDATE \"HR\".\"EMP\" SET \"NAME\" = 'Bob', \"HIRED\" = '02-JAN-26' WHERE ROWID = CHARTOROWID('AAA')"
        );
        assert_eq!(insert(Db::Oracle, "T", &cols, Some(0), &old, &[]), "INSERT INTO T (\"ID\", \"NAME\") VALUES (1, 'O''Neil')");
        // Staged BLOBs bind as parameters, even when the cell text did not change.
        assert_eq!(
            update(Db::Oracle, "T", &cols, &key, Some(0), &old, &old, &[3]).unwrap(),
            "UPDATE T SET \"HIRED\" = :1 WHERE ROWID = CHARTOROWID('AAA')"
        );
        assert_eq!(insert(Db::Postgres, "t", &cols, Some(0), &old, &[2, 3]), "INSERT INTO t (\"ID\", \"NAME\", \"HIRED\") VALUES (1, $1, $2)");
        let cols = vec![col("a", "INT", true), col("b", "VARCHAR", false)];
        let key = Key::new(&cols, None, &[]);
        assert_eq!(delete(Db::Mysql, "`t`", &cols, &key, &[Some("1".into()), None]), "DELETE FROM `t` WHERE `a` = 1 AND `b` IS NULL LIMIT 1");
        let key = Key::new(&cols, None, &["A".into()]);
        assert_eq!(delete(Db::Mssql, "[t]", &cols, &key, &[Some("1".into()), None]), "DELETE FROM [t] WHERE [a] = 1");
        assert_eq!(insert(Db::Mssql, "[t]", &cols, None, &[Some("1".into()), None], &[1]), "INSERT INTO [t] ([a], [b]) VALUES (1, @P1)");
        let d = col("D", "DATE", false);
        assert_eq!(literal(Db::Oracle, &d, &Some("2026-01-02".into())), "TO_TIMESTAMP('2026-01-02', 'YYYY-MM-DD')");
        assert_eq!(literal(Db::Oracle, &d, &Some("2026-01-02T03:04".into())), "TO_TIMESTAMP('2026-01-02 03:04:00', 'YYYY-MM-DD HH24:MI:SS')");
        assert_eq!(literal(Db::Oracle, &col("T", "TIMESTAMP(6)", false), &Some("2026-01-02 03:04:05.5".into())), "TO_TIMESTAMP('2026-01-02 03:04:05.5', 'YYYY-MM-DD HH24:MI:SS.FF')");
        assert_eq!(literal(Db::Oracle, &d, &Some("02-JAN-26".into())), "'02-JAN-26'", "NLS-formatted grid text stays implicit");
        assert_eq!(literal(Db::Postgres, &col("d", "date", false), &Some("2026-01-02".into())), "'2026-01-02'");
        let clob = col("c", "CLOB", false);
        assert!(text_needs_bind(Db::Oracle, &clob, &Some("é".repeat(2001))));
        assert!(!text_needs_bind(Db::Oracle, &clob, &Some("x".repeat(4000))));
        assert!(!text_needs_bind(Db::Postgres, &clob, &Some("x".repeat(9000))));
        let blob = col("b", "BLOB", false);
        assert_eq!(literal(Db::Oracle, &blob, &Some("504B".into())), "HEXTORAW('504B')");
        assert_eq!(literal(Db::Sqlite, &blob, &Some("0x504B".into())), "X'504B'");
        assert_eq!(literal(Db::Postgres, &col("b", "bytea", false), &Some("\\x504b".into())), "'\\x504B'::bytea");
    }
}
